#!/usr/bin/env bash
# Writes the Homebrew formula for a published release.
# usage: packaging/homebrew/render_formula.sh <version> <SHA256SUMS> > Formula/osie.rb
# SHA256SUMS is the file published with the GitHub release.
set -euo pipefail
v="${1:?version, e.g. 0.1.0}"
sums="${2:?path to SHA256SUMS}"
sha() {
  local f="osie-${v}-$1.tar.gz" s
  s=$(awk -v f="$f" '$2 == f || $2 == "*"f {print $1}' "$sums")
  [[ -n "$s" ]] || { echo "missing $f in $sums" >&2; exit 1; }
  echo "$s"
}
base="https://github.com/deosha/osie/releases/download/v${v}"
cat <<RUBY
# Generated by packaging/homebrew/render_formula.sh from the v${v} release checksums.
class Osie < Formula
  desc "Local, read-only OS intelligence engine using native macOS/Linux observations"
  homepage "https://github.com/deosha/osie"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "${base}/osie-${v}-macos-arm64.tar.gz"
      sha256 "$(sha macos-arm64)"
    end
    on_intel do
      url "${base}/osie-${v}-macos-x86_64.tar.gz"
      sha256 "$(sha macos-x86_64)"
    end
  end

  on_linux do
    on_arm do
      url "${base}/osie-${v}-linux-aarch64.tar.gz"
      sha256 "$(sha linux-aarch64)"
    end
    on_intel do
      url "${base}/osie-${v}-linux-x86_64.tar.gz"
      sha256 "$(sha linux-x86_64)"
    end
  end

  def install
    # Same layout as the archive: the binary finds its model at ../share/osie/models.
    bin.install Dir["bin/*"]
    (pkgshare/"models").install Dir["share/osie/models/*"]
    doc.install Dir["share/doc/osie/*"]
  end

  test do
    assert_match "installed with the binary", shell_output("#{bin}/osie version")
    assert_match(/CPU world model: .*world_cpu.osiewm/, shell_output("#{bin}/osie version"))
    assert_match "diagnose_slow", shell_output("#{bin}/osie parse 'why is my computer slow'")
    assert_match "won't", shell_output("#{bin}/osie ask 'kill pid 1'")
  end
end
RUBY
